<?php
require '_init.php';$pageTitle='Manage Categories';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if(isset($_POST['delete'])){$s=$pdo->prepare("DELETE FROM categories WHERE id=?");$s->execute([(int)$_POST['id']]);set_flash('Category deleted.');redirect('categories.php');}$name=trim($_POST['name']??'');if($name==='')$error='Category name is required.';else{$s=$pdo->prepare("INSERT INTO categories(name) VALUES(?)");try{$s->execute([$name]);set_flash('Category added.');redirect('categories.php');}catch(PDOException $e){$error='Category already exists.';}}}
$rows=$pdo->query("SELECT c.*,COUNT(f.id) food_count FROM categories c LEFT JOIN food_items f ON f.category_id=c.id GROUP BY c.id ORDER BY c.name")->fetchAll();require '../includes/header.php';
?>
<section class="page-heading"><span class="eyebrow">ADMIN</span><h1>Categories</h1></section><div class="form-card narrow"><form method="post" class="stack-form"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><label>New category<input name="name" required maxlength="80" placeholder="e.g. Burgers"></label><button class="btn">Add category</button><?php if($error): ?><div class="alert error"><?= e($error) ?></div><?php endif; ?></form></div><div class="table-wrap"><table><thead><tr><th>Category</th><th>Food items</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= e($r['name']) ?></td><td><?= (int)$r['food_count'] ?></td><td><form method="post" onsubmit="return confirm('Delete this category? Food items will become uncategorized.')"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><button class="link-danger" name="delete">Delete</button></form></td></tr><?php endforeach; ?></tbody></table></div>
<?php require '../includes/footer.php'; ?>
